'use strict';(()=>{const map={grow:'grow',merge:'merge',adventure:'adventure'};let own=location.pathname.includes('merge')?'merge':location.pathname.includes('adventure')?'adventure':'grow';if(parent===window&&!['localhost','127.0.0.1'].includes(location.hostname)){location.replace('/#'+own);return}document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||parent===window)return;const url=new URL(a.href);if(url.origin!==location.origin)return;let game=url.pathname.includes('merge')?'merge':url.pathname.includes('adventure')?'adventure':url.pathname==='/'||url.pathname.includes('grow')?'grow':null;if(game){e.preventDefault();parent.postMessage({type:'switch-game',game},location.origin)}});if(parent!==window){const h=document.querySelector('header');if(own==='grow'&&h)h.style.display='none';if(own==='merge'){const nav=document.querySelector('header');if(nav)nav.style.display='none'}}})();
